"use client";

import { CourseHeader } from "@/components/app-pages/course-detail page/course-header";
import { CourseCurriculum } from "@/components/app-pages/course-detail page/course-curriculum";
import { CourseDetails } from "@/components/app-pages/course-detail page/course-details";
import { InstructorProfile } from "@/components/app-pages/course-detail page/instructor-profile";
import { VideoPlayer } from "@/components/app-pages/course-detail page/video-player";
import { cn } from "@/lib/utils";

export interface CourseDetailPageProps {
  className?: string;
}

export function CourseDetailPage({ className }: CourseDetailPageProps) {
  return (
    <div className={cn("bg-background min-h-screen w-full", className)}>
      <CourseHeader />

      <main className="mx-auto max-w-7xl px-4 py-8">
        <div className="grid grid-cols-1 gap-8 lg:grid-cols-3">
          <div className="space-y-6 lg:col-span-2">
            <VideoPlayer />
            <CourseDetails />
            <InstructorProfile />
          </div>

          <div className="hidden lg:col-span-1 lg:block">
            <div className="sticky top-20">
              <CourseCurriculum />
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}

"use client";

import { useState } from "react";
import { ArrowLeft } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  Drawer,
  DrawerContent,
  DrawerHeader,
  DrawerTitle,
} from "@/components/ui/drawer";
import { CourseCurriculum } from "./course-curriculum";
import { CircleProgress } from "./circle-progress";
import { lessons } from "./data";

const completedCount = lessons.filter((l) => l.completed).length;
const progress = Math.round((completedCount / lessons.length) * 100);

export function CourseHeader() {
  const [open, setOpen] = useState(false);

  return (
    <>
      <header className="bg-background/95 sticky top-0 z-50 border-b backdrop-blur-sm">
        <div className="mx-auto max-w-7xl px-4 py-3">
          <div className="flex items-center justify-between gap-4">
            {/* Left: back + title */}
            <div className="flex min-w-0 items-center gap-3">
              <Button variant="primary" size="sm" className="shrink-0 gap-1.5">
                <ArrowLeft className="h-3.5 w-3.5" />
                <span className="hidden sm:inline">Courses</span>
              </Button>
              <div className="bg-border hidden h-5 w-px sm:block" />
              <h1 className="text-foreground truncate text-sm font-medium sm:text-base">
                The Ultimate Guide to Usability Testing and UX Law
              </h1>
            </div>

            {/* Mobile: curriculum drawer trigger */}
            <Button
              variant="primary"
              size="sm"
              className="shrink-0 gap-2 lg:hidden"
              onClick={() => setOpen(true)}
            >
              <CircleProgress value={progress} size={22} strokeWidth={2} />
              <span className="hidden text-sm sm:inline">Curriculum</span>
            </Button>
          </div>
        </div>
      </header>

      {/* Mobile curriculum drawer */}
      <Drawer open={open} onOpenChange={setOpen} direction="bottom">
        <DrawerContent className="max-h-[85vh]">
          <DrawerHeader className="pb-2">
            <DrawerTitle>Course Curriculum</DrawerTitle>
          </DrawerHeader>
          <div className="overflow-y-auto px-4 pb-6">
            <CourseCurriculum />
          </div>
        </DrawerContent>
      </Drawer>
    </>
  );
}

"use client";

import { useState, useRef, useCallback } from "react";
import {
  Play,
  Pause,
  Volume2,
  VolumeX,
  Maximize,
  Settings,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { cn } from "@/lib/utils";

const TOTAL_SECONDS = 45 * 60 + 32;

const formatTime = (s: number) => {
  const m = Math.floor(s / 60);
  const sec = Math.floor(s % 60);
  return `${m}:${String(sec).padStart(2, "0")}`;
};

export function VideoPlayer() {
  const [isPlaying, setIsPlaying] = useState(false);
  const [isMuted, setIsMuted] = useState(false);
  const [progress, setProgress] = useState(23 / TOTAL_SECONDS);
  const progressRef = useRef<HTMLDivElement>(null);

  const currentSeconds = Math.floor(progress * TOTAL_SECONDS);

  const handleProgressClick = useCallback(
    (e: React.MouseEvent<HTMLDivElement>) => {
      const bar = progressRef.current;
      if (!bar) return;
      const rect = bar.getBoundingClientRect();
      const ratio = Math.max(
        0,
        Math.min(1, (e.clientX - rect.left) / rect.width),
      );
      setProgress(ratio);
    },
    [],
  );

  return (
    <Card className="overflow-hidden py-0 shadow-none">
      <div className="relative aspect-video bg-slate-900">
        {/* Thumbnail */}
        <img
          src="https://plus.unsplash.com/premium_photo-1682126202084-f23c6cee5dbc?q=80&w=2940&auto=format&fit=crop"
          alt="Course preview"
          className="h-full w-full object-cover opacity-80"
        />

        {/* Bottom gradient */}
        <div className="absolute right-0 bottom-0 left-0 h-24 bg-linear-to-t from-black/80 to-transparent" />

        {/* Center play/pause button */}
        <button
          onClick={() => setIsPlaying((p) => !p)}
          className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 transition-transform hover:scale-110 active:scale-95"
        >
          <div className="flex size-14 items-center justify-center rounded-full bg-white/20 ring-2 ring-white/60 backdrop-blur-sm">
            {isPlaying ? (
              <Pause className="size-6 fill-white text-white" />
            ) : (
              <Play className="ml-1 size-6 fill-white text-white" />
            )}
          </div>
        </button>

        {/* Bottom controls */}
        <div className="absolute right-0 bottom-0 left-0 px-4 pb-3">
          {/* Progress bar */}
          <div
            ref={progressRef}
            onClick={handleProgressClick}
            className="group mb-3 h-1 cursor-pointer rounded-full bg-white/30 transition-all hover:h-1.5"
          >
            <div
              className="relative h-full rounded-full bg-white transition-all"
              style={{ width: `${progress * 100}%` }}
            >
              <div className="absolute top-1/2 right-0 size-3 translate-x-1/2 -translate-y-1/2 scale-0 rounded-full bg-white shadow transition-transform group-hover:scale-100" />
            </div>
          </div>

          {/* Controls row */}
          <div className="flex items-center justify-between text-white">
            <div className="flex items-center gap-2">
              <Button
                size="sm"
                variant="ghost"
                className="size-7 text-white hover:bg-white/20"
                onClick={() => setIsPlaying((p) => !p)}
              >
                {isPlaying ? (
                  <Pause className="size-4" />
                ) : (
                  <Play className="size-4" />
                )}
              </Button>
              <Button
                size="sm"
                variant="ghost"
                className="size-7 text-white hover:bg-white/20"
                onClick={() => setIsMuted((m) => !m)}
              >
                {isMuted ? (
                  <VolumeX className="size-4" />
                ) : (
                  <Volume2 className="size-4" />
                )}
              </Button>
              <span className={cn("text-xs tabular-nums", "text-white/90")}>
                {formatTime(currentSeconds)} / {formatTime(TOTAL_SECONDS)}
              </span>
            </div>

            <div className="flex items-center gap-1">
              <Button
                size="sm"
                variant="ghost"
                className="size-7 text-white hover:bg-white/20"
              >
                <Settings className="size-4" />
              </Button>
              <Button
                size="sm"
                variant="ghost"
                className="size-7 text-white hover:bg-white/20"
              >
                <Maximize className="size-4" />
              </Button>
            </div>
          </div>
        </div>
      </div>
    </Card>
  );
}

"use client";

import { useState } from "react";
import { CheckCircle2, Circle, Clock, Heart, Play } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { ScrollArea } from "@/components/ui/scroll-area";
import { cn } from "@/lib/utils";
import { lessons } from "./data";

const completedCount = lessons.filter((l) => l.completed).length;
const progressPercent =
  lessons.length > 0 ? Math.round((completedCount / lessons.length) * 100) : 0;

export function CourseCurriculum() {
  const [activeId, setActiveId] = useState(3);
  const [saved, setSaved] = useState(false);

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap gap-2">
        <Badge variant="secondary">Advanced</Badge>
        <Badge variant="outline">Live Class</Badge>
        <Badge variant="outline">{lessons.length} Lessons</Badge>
      </div>

      <Card className="shadow-none">
        <CardContent className="space-y-4">
          <div className="space-y-1.5">
            <div className="text-muted-foreground flex justify-between text-xs">
              <span>
                {completedCount} of {lessons.length} completed
              </span>
              <span>{progressPercent}%</span>
            </div>
            <Progress value={progressPercent} className="h-1.5 bg-muted" />
          </div>

          <div className="space-y-2">
            <Button className="w-full gap-2" size="lg">
              <Play />
              Continue Learning
            </Button>
            <Button
              variant="primary"
              className="w-full gap-2"
              onClick={() => setSaved((s) => !s)}
            >
              <Heart
                className={cn("size-4", saved && "fill-current text-rose-500")}
              />
              {saved ? "Saved" : "Save for Later"}
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* Curriculum */}
      <Card className="shadow-none">
        <CardHeader className="pb-3">
          <CardTitle className="flex items-center justify-between text-base">
            <span className="flex items-center gap-2">
              <Play className="text-primary size-4" />
              Course Curriculum
            </span>
            <span className="text-muted-foreground text-xs font-normal">
              {completedCount}/{lessons.length}
            </span>
          </CardTitle>
        </CardHeader>
        <CardContent className="p-0">
          <ScrollArea className="lg:h-[420px]">
            <div className="pb-2">
              {lessons.map((lesson) => {
                const isActive = lesson.id === activeId;
                return (
                  <button
                    key={lesson.id}
                    onClick={() => setActiveId(lesson.id)}
                    className={cn(
                      "hover:bg-muted/40 flex w-full items-start gap-3 border-l-2 px-4 py-3 text-left transition-colors",
                      isActive
                        ? "border-l-primary bg-primary/5"
                        : "border-l-transparent",
                    )}
                  >
                    {/* Status icon */}
                    <div className="mt-0.5 shrink-0">
                      {lesson.completed ? (
                        <CheckCircle2 className="size-4 text-emerald-500" />
                      ) : isActive ? (
                        <div className="bg-primary flex size-4 items-center justify-center rounded-full">
                          <Play className="text-primary-foreground size-2.5 fill-current" />
                        </div>
                      ) : (
                        <Circle className="text-muted-foreground/40 size-4" />
                      )}
                    </div>

                    {/* Title + duration */}
                    <div className="min-w-0 flex-1">
                      <p
                        className={cn(
                          "truncate text-sm",
                          isActive
                            ? "text-primary font-medium"
                            : lesson.completed
                              ? "text-muted-foreground"
                              : "text-foreground",
                        )}
                      >
                        {lesson.title}
                      </p>
                      <div className="text-muted-foreground mt-0.5 flex items-center gap-1">
                        <Clock className="size-3" />
                        <span className="text-xs">{lesson.duration}</span>
                      </div>
                    </div>
                  </button>
                );
              })}
            </div>
          </ScrollArea>
        </CardContent>
      </Card>
    </div>
  );
}

interface CircleProgressProps {
  value: number; // 0–100
  size?: number;
  strokeWidth?: number;
}

export function CircleProgress({
  value,
  size = 30,
  strokeWidth = 2.5,
}: CircleProgressProps) {
  const center = size / 2;
  const radius = center - strokeWidth - 0.5;
  const circumference = 2 * Math.PI * radius;
  const clamped = Math.max(0, Math.min(100, value));
  const offset = circumference * (1 - clamped / 100);
  const fontSize = Math.round(size * 0.26);

  return (
    <svg
      width={size}
      height={size}
      viewBox={`0 0 ${size} ${size}`}
      aria-label={`${clamped}% complete`}
      style={{ flexShrink: 0 }}
    >
      {/* Track */}
      <circle
        cx={center}
        cy={center}
        r={radius}
        fill="none"
        stroke="currentColor"
        strokeWidth={strokeWidth}
        opacity={0.2}
      />
      {/* Progress arc */}
      <circle
        cx={center}
        cy={center}
        r={radius}
        fill="none"
        stroke="currentColor"
        strokeWidth={strokeWidth}
        strokeDasharray={`${circumference} ${circumference}`}
        strokeDashoffset={offset}
        strokeLinecap="round"
        transform={`rotate(-90 ${center} ${center})`}
        style={{ transition: "stroke-dashoffset 0.4s ease" }}
      />
      {/* Percentage label */}
      <text
        x={center}
        y={center}
        textAnchor="middle"
        dominantBaseline="central"
        fontSize={fontSize}
        fontWeight={600}
        fill="currentColor"
      >
        {clamped}%
      </text>
    </svg>
  );
}

"use client";

import OnboardingFlow from "@/components/app-pages/onboardingflow-page-preview/onboarding";
import { cn } from "@/lib/utils";

export interface OnboardingFlowPageProps {
  className?: string;
}

export function OnboardingFlowPage({ className }: OnboardingFlowPageProps) {
  return (
    <OnboardingFlow
      className={cn("bg-background min-h-screen w-full", className)}
    />
  );
}

"use client";

import { useState } from "react";
import {
  ChevronLeft,
  ChevronRight,
  User,
  Briefcase,
  Factory,
  Globe,
  CheckCircle2,
  CreditCard,
  Building2,
  Sparkles,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import { Separator } from "@/components/ui/separator";
import { cn } from "@/lib/utils";
import { useOnboardingStore } from "./store";
import type { FormData } from "./store";
import { StepIndicator } from "./step-indicator";
import { CoverPanel } from "./cover-panel";
import {
  ResizableHandle,
  ResizablePanel,
  ResizablePanelGroup,
} from "@/components/ui/resizable";

function formatCardNumber(value: string) {
  return value
    .replace(/\D/g, "")
    .slice(0, 16)
    .replace(/(.{4})/g, "$1 ")
    .trim();
}

function validateStep(step: number, data: FormData) {
  switch (step) {
    case 2:
      if (!data.teamName.trim()) return "Team account name is required";
      return null;
    case 3:
      if (!data.companyName.trim()) return "Company name is required";
      if (!data.industry) return "Please select an industry";
      return null;
    case 4:
      if (!data.nameOnCard.trim()) return "Name on card is required";
      if (data.cardNumber.replace(/\s/g, "").length < 16)
        return "Enter a valid 16-digit card number";
      if (!data.expirationMonth) return "Select expiration month";
      if (!data.expirationYear) return "Select expiration year";
      if (data.cvv.length < 3) return "Enter a valid CVV";
      return null;
    default:
      return null;
  }
}

export default function OnboardingFlow({ className }: { className?: string }) {
  const { currentStep, formData, next, prev, update, reset } =
    useOnboardingStore();
  const [error, setError] = useState<string | null>(null);

  const handleNext = () => {
    const err = validateStep(currentStep, formData);
    if (err) {
      setError(err);
      return;
    }
    setError(null);
    next();
  };

  const handlePrev = () => {
    setError(null);
    prev();
  };

  const handleUpdate = <K extends keyof FormData>(
    field: K,
    value: FormData[K],
  ) => {
    setError(null);
    update(field, value);
  };

  const renderStep = () => {
    switch (currentStep) {
      case 1:
        return (
          <div className="space-y-5">
            <div>
              <h2 className="text-lg font-semibold">Choose Account Type</h2>
              <p className="text-muted-foreground mt-1 text-sm">
                Select the type that best fits your use case.
              </p>
            </div>
            <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
              {[
                {
                  value: "personal" as const,
                  icon: User,
                  title: "Personal Account",
                  desc: "For individuals and freelancers",
                },
                {
                  value: "corporate" as const,
                  icon: Briefcase,
                  title: "Corporate Account",
                  desc: "For teams and organizations",
                },
              ].map(({ value, icon: Icon, title, desc }) => (
                <button
                  key={value}
                  onClick={() => handleUpdate("accountType", value)}
                  className={cn(
                    "flex flex-col items-start gap-3 rounded-xl border p-5 text-left transition-all",
                    formData.accountType === value
                      ? "border-primary bg-primary/5 ring-2 ring-primary"
                      : "border-border hover:border-primary/50 hover:bg-muted/50",
                  )}
                >
                  <div
                    className={cn(
                      "flex size-10 shrink-0 items-center justify-center rounded-lg",
                      formData.accountType === value
                        ? "bg-primary/10"
                        : "bg-muted",
                    )}
                  >
                    <Icon
                      className={cn(
                        "size-5",
                        formData.accountType === value
                          ? "text-primary"
                          : "text-muted-foreground",
                      )}
                    />
                  </div>
                  <div className="min-w-0">
                    <div className="font-medium">{title}</div>
                    <div className="text-muted-foreground mt-0.5 text-sm">
                      {desc}
                    </div>
                  </div>
                </button>
              ))}
            </div>
          </div>
        );

      case 2:
        return (
          <div className="space-y-5">
            <div>
              <h2 className="text-lg font-semibold">Account Info</h2>
              <p className="text-muted-foreground mt-1 text-sm">
                Set up your account details.
              </p>
            </div>
            <div className="space-y-1.5">
              <Label>Team Size</Label>
              <div className="grid grid-cols-2 gap-2 sm:grid-cols-4">
                {["1-1", "2-10", "10-50", "50+"].map((size) => (
                  <button
                    key={size}
                    onClick={() => handleUpdate("teamSize", size)}
                    className={cn(
                      "rounded-lg border py-3 text-sm font-medium transition-all",
                      formData.teamSize === size
                        ? "border-primary bg-primary/5 text-primary ring-2 ring-primary"
                        : "border-border text-muted-foreground hover:border-primary/50 hover:text-foreground",
                    )}
                  >
                    {size}
                  </button>
                ))}
              </div>
            </div>
            <div className="space-y-1.5">
              <Label htmlFor="teamName">
                Team Account Name <span className="text-destructive">*</span>
              </Label>
              <Input
                id="teamName"
                placeholder="e.g. Acme Corp"
                value={formData.teamName}
                onChange={(e) => handleUpdate("teamName", e.target.value)}
              />
            </div>
            <div className="space-y-1.5">
              <Label>Account Plan</Label>
              <RadioGroup
                value={formData.accountPlan}
                onValueChange={(v) => handleUpdate("accountPlan", v)}
                className="space-y-2"
              >
                {[
                  {
                    value: "company",
                    icon: Factory,
                    title: "Company Account",
                    desc: "Full access for teams",
                  },
                  {
                    value: "developer",
                    icon: User,
                    title: "Developer Account",
                    desc: "Ideal for building and testing",
                  },
                  {
                    value: "testing",
                    icon: Globe,
                    title: "Testing Account",
                    desc: "Sandbox environment access",
                  },
                ].map(({ value, icon: Icon, title, desc }) => (
                  <label
                    key={value}
                    htmlFor={`plan-${value}`}
                    className={cn(
                      "flex cursor-pointer items-center gap-3 rounded-lg border p-4 transition-all",
                      formData.accountPlan === value
                        ? "border-primary bg-primary/5"
                        : "border-border hover:bg-muted/50",
                    )}
                  >
                    <Icon className="text-muted-foreground size-5 shrink-0" />
                    <div className="flex-1">
                      <div className="text-sm font-medium">{title}</div>
                      <div className="text-muted-foreground text-xs">
                        {desc}
                      </div>
                    </div>
                    <RadioGroupItem value={value} id={`plan-${value}`} />
                  </label>
                ))}
              </RadioGroup>
            </div>
          </div>
        );

      case 3:
        return (
          <div className="space-y-5">
            <div>
              <h2 className="text-lg font-semibold">Business Details</h2>
              <p className="text-muted-foreground mt-1 text-sm">
                Tell us about your business.
              </p>
            </div>
            <div className="space-y-4">
              <div className="space-y-1.5">
                <Label htmlFor="companyName">
                  Company Name <span className="text-destructive">*</span>
                </Label>
                <Input
                  id="companyName"
                  placeholder="Acme Inc."
                  value={formData.companyName}
                  onChange={(e) => handleUpdate("companyName", e.target.value)}
                />
              </div>
              <div className="space-y-1.5">
                <Label>
                  Industry <span className="text-destructive">*</span>
                </Label>
                <Select
                  value={formData.industry}
                  onValueChange={(v) => handleUpdate("industry", v)}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Select your industry" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="technology">Technology</SelectItem>
                    <SelectItem value="finance">Finance</SelectItem>
                    <SelectItem value="healthcare">Healthcare</SelectItem>
                    <SelectItem value="retail">Retail & E-commerce</SelectItem>
                    <SelectItem value="education">Education</SelectItem>
                    <SelectItem value="other">Other</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-1.5">
                <Label htmlFor="website">Website</Label>
                <Input
                  id="website"
                  placeholder="https://yourcompany.com"
                  value={formData.website}
                  onChange={(e) => handleUpdate("website", e.target.value)}
                />
              </div>
            </div>
          </div>
        );

      case 4:
        return (
          <div className="space-y-5">
            <div>
              <h2 className="text-lg font-semibold">Billing Details</h2>
              <p className="text-muted-foreground mt-1 text-sm">
                Your card is stored securely and never shared.
              </p>
            </div>
            <div className="space-y-4">
              <div className="space-y-1.5">
                <Label htmlFor="nameOnCard">
                  Name on Card <span className="text-destructive">*</span>
                </Label>
                <Input
                  id="nameOnCard"
                  placeholder="John Doe"
                  value={formData.nameOnCard}
                  onChange={(e) => handleUpdate("nameOnCard", e.target.value)}
                />
              </div>
              <div className="space-y-1.5">
                <Label htmlFor="cardNumber">
                  Card Number <span className="text-destructive">*</span>
                </Label>
                <div className="relative">
                  <Input
                    id="cardNumber"
                    placeholder="0000 0000 0000 0000"
                    value={formData.cardNumber}
                    onChange={(e) =>
                      handleUpdate(
                        "cardNumber",
                        formatCardNumber(e.target.value),
                      )
                    }
                    inputMode="numeric"
                    className="pr-10"
                  />
                  <CreditCard className="text-muted-foreground absolute top-1/2 right-3 size-4 -translate-y-1/2" />
                </div>
              </div>
