"use client";

import { useMemo } from "react";
import { Search, LayoutGrid, List, SlidersHorizontal, StickyNote, X, Pin } from "lucide-react";
import {
  DndContext,
  closestCenter,
  PointerSensor,
  useSensor,
  useSensors,
  type DragEndEvent
} from "@dnd-kit/core";
import {
  SortableContext,
  rectSortingStrategy,
  verticalListSortingStrategy
} from "@dnd-kit/sortable";
import { restrictToWindowEdges } from "@dnd-kit/modifiers";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Sheet, SheetContent, SheetTitle } from "@/components/ui/sheet";
import { Toggle } from "@/components/ui/toggle";
import { useNoteStore, useUIStore } from "./store";
import { NoteCard } from "@/components/app-pages/notes/note-card";
import { NoteForm } from "@/components/app-pages/notes/note-form";
import { NoteSidebar } from "@/components/app-pages/notes/note-sidebar";

export function NoteApp() {
  const { notes, viewMode, setViewMode, addNote, reorderNotes } = useNoteStore();
  const { search, activeCategory, activeColor, sidebarOpen, setSearch, setSidebarOpen, clearFilters } = useUIStore();

  const isFiltered = !!(search || activeCategory || activeColor);

  const filtered = useMemo(() => {
    let result = [...notes];

    if (search) {
      const q = search.toLowerCase();
      result = result.filter(
        (n) =>
          n.title.toLowerCase().includes(q) ||
          n.content.toLowerCase().includes(q) ||
          n.category.toLowerCase().includes(q)
      );
    }
    if (activeCategory) result = result.filter((n) => n.category === activeCategory);
    if (activeColor) result = result.filter((n) => n.color === activeColor);

    if (isFiltered) {
      return result.sort(
        (a, b) => new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime()
      );
    }

    return result.sort((a, b) => {
      if (a.pinned !== b.pinned) return a.pinned ? -1 : 1;
      return a.order - b.order;
    });
  }, [notes, search, activeCategory, activeColor, isFiltered]);

  const pinnedNotes = !isFiltered ? filtered.filter((n) => n.pinned) : [];
  const regularNotes = !isFiltered ? filtered.filter((n) => !n.pinned) : filtered;

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 5 } })
  );

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;
    if (over && active.id !== over.id) {
      reorderNotes(String(active.id), String(over.id));
    }
  };

  const gridClass =
    viewMode === "grid"
      ? "grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-3"
      : "flex flex-col gap-2";

  const strategy = viewMode === "grid" ? rectSortingStrategy : verticalListSortingStrategy;

  const renderSection = (sectionNotes: typeof filtered) => (
    <SortableContext items={sectionNotes.map((n) => n.id)} strategy={strategy}>
      <div className={gridClass}>
        {sectionNotes.map((note) => (
          <NoteCard key={note.id} note={note} viewMode={viewMode} canDrag={!isFiltered} />
        ))}
      </div>
    </SortableContext>
  );

  return (
    <DndContext
      sensors={sensors}
      collisionDetection={closestCenter}
      modifiers={[restrictToWindowEdges]}
      onDragEnd={handleDragEnd}>
      <div className="bg-background flex h-screen overflow-hidden">
        {/* Desktop Sidebar */}
        <aside className="hidden w-52 shrink-0 border-r lg:flex lg:flex-col">
          <div className="flex items-center gap-2 border-b px-4 py-4">
            <StickyNote className="text-primary size-5" />
            <span className="font-semibold">Notes</span>
          </div>
          <div className="flex-1 overflow-y-auto">
            <NoteSidebar />
          </div>
          <div className="border-t p-3">
            <NoteForm onSubmit={addNote} />
          </div>
        </aside>

        {/* Mobile Sidebar Sheet */}
        <Sheet open={sidebarOpen} onOpenChange={setSidebarOpen}>
          <SheetContent side="left" className="w-64 p-0">
            <SheetTitle className="sr-only">Filters</SheetTitle>
            <div className="flex items-center gap-2 border-b px-4 py-4">
              <StickyNote className="text-primary size-5" />
              <span className="font-semibold">Notes</span>
            </div>
            <div className="flex-1 overflow-y-auto">
              <NoteSidebar />
            </div>
          </SheetContent>
        </Sheet>

        {/* Main */}
        <div className="flex min-w-0 flex-1 flex-col">
          {/* Header */}
          <header className="flex shrink-0 items-center gap-2 border-b px-4 py-3">
            <Button
              variant="ghost"
              size="icon"
              className="lg:hidden"
              onClick={() => setSidebarOpen(true)}>
              <SlidersHorizontal className="size-4" />
            </Button>

            <div className="relative max-w-sm flex-1">
              <Search className="text-muted-foreground absolute top-1/2 left-3 size-3.5 -translate-y-1/2" />
              <Input
                placeholder="Search notes..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className="h-9 pl-8"
              />
              {search && (
                <Button
                  variant="ghost"
                  size="icon"
                  className="absolute top-1/2 right-1 size-7 -translate-y-1/2"
                  onClick={() => setSearch("")}>
                  <X className="size-3.5" />
                </Button>
              )}
            </div>

            <div className="ml-auto flex items-center gap-1">
              {isFiltered && (
                <Button
                  variant="ghost"
                  size="sm"
                  className="text-muted-foreground h-8 gap-1 text-xs"
                  onClick={clearFilters}>
                  <X className="size-3" />
                  Clear filters
                </Button>
              )}
              <div className="flex rounded-lg border p-0.5">
                <Toggle
                  pressed={viewMode === "grid"}
                  onPressedChange={() => setViewMode("grid")}
                  size="sm"
                  className="data-[state=on]:bg-muted size-7 rounded-md">
                  <LayoutGrid className="size-3.5" />
                </Toggle>
                <Toggle
                  pressed={viewMode === "list"}
                  onPressedChange={() => setViewMode("list")}
                  size="sm"
                  className="data-[state=on]:bg-muted size-7 rounded-md">
                  <List className="size-3.5" />
                </Toggle>
              </div>

              <div className="lg:hidden">
                <NoteForm
                  onSubmit={addNote}
                  trigger={
                    <Button size="sm" className="h-8 gap-1.5">
                      Add note
                    </Button>
                  }
                />
              </div>
            </div>
          </header>

          {/* Content */}
          <div className="flex-1 overflow-y-auto p-4 lg:p-5">
            {filtered.length === 0 ? (
              <div className="flex h-full items-center justify-center">
                <div className="text-center">
                  <StickyNote className="text-muted-foreground/30 mx-auto mb-3 size-12" />
                  <p className="text-muted-foreground text-sm font-medium">No notes found</p>
                  <p className="text-muted-foreground mt-1 text-xs">
                    {isFiltered ? "Try adjusting your filters" : "Create your first note"}
                  </p>
                </div>
              </div>
            ) : (
              <div className="space-y-6">
                {pinnedNotes.length > 0 && (
                  <div>
                    <div className="mb-3 flex items-center gap-1.5">
                      <Pin className="text-muted-foreground size-3" />
                      <span className="text-muted-foreground text-xs font-semibold tracking-wider uppercase">
                        Pinned
                      </span>
                    </div>
                    {renderSection(pinnedNotes)}
                  </div>
                )}

                {regularNotes.length > 0 && (
                  <div>
                    {pinnedNotes.length > 0 && (
                      <div className="mb-3 flex items-center gap-1.5">
                        <span className="text-muted-foreground text-xs font-semibold tracking-wider uppercase">
                          {isFiltered ? `${regularNotes.length} results` : "Notes"}
                        </span>
                      </div>
                    )}
                    {renderSection(regularNotes)}
                  </div>
                )}

                {!isFiltered && (
                  <p className="text-muted-foreground/50 pt-2 text-center text-xs">
                    Drag notes to reorder
                  </p>
                )}
              </div>
            )}
          </div>
        </div>
      </div>
    </DndContext>
  );
}

"use client";

import { GripVertical, MoreHorizontal, Pin, PinOff, Pencil, Trash2 } from "lucide-react";
import { useSortable } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger
} from "@/components/ui/dropdown-menu";
import { cn } from "@/lib/utils";
import { NOTE_COLORS, type Note } from "@/components/app-pages/notes/store";
import { NoteForm } from "@/components/app-pages/notes/note-form";
import { useNoteStore } from "@/components/app-pages/notes/store";

interface NoteCardProps {
  note: Note;
  viewMode: "grid" | "list";
  canDrag: boolean;
}

function timeAgo(iso: string) {
  const diff = Date.now() - new Date(iso).getTime();
  const m = Math.floor(diff / 60000);
  if (m < 1) return "Just now";
  if (m < 60) return `${m}m ago`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h}h ago`;
  const d = Math.floor(h / 24);
  if (d < 7) return `${d}d ago`;
  return new Date(iso).toLocaleDateString(undefined, { month: "short", day: "numeric" });
}

export function NoteCard({ note, viewMode, canDrag }: NoteCardProps) {
  const { updateNote, deleteNote, togglePin } = useNoteStore();
  const colors = NOTE_COLORS[note.color];

  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging
  } = useSortable({ id: note.id, disabled: !canDrag });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition: isDragging ? "none" : transition
  };

  const actions = (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button
          variant="ghost"
          size="icon"
          className="size-7 opacity-0 group-hover:opacity-100 focus:opacity-100 shrink-0"
          onClick={(e) => e.stopPropagation()}>
          <MoreHorizontal className="size-3.5" />
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="w-40">
        <NoteForm
          defaultValues={note}
          trigger={
            <DropdownMenuItem onSelect={(e) => e.preventDefault()}>
              <Pencil className="size-3.5 mr-2" />
              Edit
            </DropdownMenuItem>
          }
          onSubmit={(values) => updateNote(note.id, values)}
        />
        <DropdownMenuItem onClick={() => togglePin(note.id)}>
          {note.pinned ? (
            <><PinOff className="size-3.5 mr-2" />Unpin</>
          ) : (
            <><Pin className="size-3.5 mr-2" />Pin</>
          )}
        </DropdownMenuItem>
        <DropdownMenuSeparator />
        <DropdownMenuItem
          className="text-destructive focus:text-destructive"
          onClick={() => deleteNote(note.id)}>
          <Trash2 className="size-3.5 mr-2" />
          Delete
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );

  const gripHandle = canDrag && (
    <GripVertical
      className="text-muted-foreground/40 size-4 shrink-0 cursor-grab active:cursor-grabbing touch-none"
      {...attributes}
      {...listeners}
    />
  );

  if (viewMode === "list") {
    return (
      <div
        ref={setNodeRef}
        style={style}
        className={cn(
          "group flex items-start gap-3 rounded-xl border px-4 py-3 transition-all",
          colors.bg,
          colors.border,
          isDragging && "opacity-40 scale-[0.98] z-50"
        )}>
        {gripHandle && <div className="mt-0.5">{gripHandle}</div>}
        <div className="min-w-0 flex-1">
          <div className="flex items-start justify-between gap-2">
            <div className="flex items-center gap-2 min-w-0">
              {note.pinned && <Pin className="size-3 text-muted-foreground shrink-0" />}
              <p className="truncate text-sm font-semibold">{note.title}</p>
            </div>
            <div className="flex items-center gap-2 shrink-0">
              <Badge variant="secondary" className="text-[11px] h-5">{note.category}</Badge>
              <span className="text-muted-foreground text-[11px]">{timeAgo(note.updatedAt)}</span>
              {actions}
            </div>
          </div>
          {note.content && (
            <p className="text-muted-foreground mt-0.5 truncate text-xs">{note.content}</p>
          )}
        </div>
      </div>
    );
  }

  return (
    <div
      ref={setNodeRef}
      style={style}
      className={cn(
        "group flex flex-col rounded-xl border p-4 transition-all",
        colors.bg,
        colors.border,
