export function ChatMain() {
  const {
    activeChatId,
    contacts,
    groups,
    messages,
    sendMessage,
    setMobileDrawerOpen,
  } = useChatStore();
  const isMobile = useIsMobile();
  const [input, setInput] = useState("");
  const messagesRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const allContacts = [...contacts, ...groups];
  const activeContact = allContacts.find((c) => c.id === activeChatId);
  const activeMessages = messages[activeChatId] ?? [];

  const avatarByFirstName = useMemo(() => {
    const map = new Map<string, string>();
    for (const c of contacts) {
      const first = c.name.split(" ")[0];
      if (first && c.avatar) map.set(first, c.avatar);
    }
    return map;
  }, [contacts]);

  const scrollToBottom = (behavior: ScrollBehavior = "smooth") => {
    const el = messagesRef.current;
    if (el) el.scrollTop = el.scrollHeight;
  };

  useEffect(() => {
    scrollToBottom("smooth");
  }, [activeMessages.length]);

  // Reset input and scroll when switching chats
  useEffect(() => {
    setInput("");
    scrollToBottom("instant");
  }, [activeChatId]);

  const handleSend = () => {
    const trimmed = input.trim();
    if (!trimmed) return;
    sendMessage(activeChatId, trimmed);
    setInput("");
    textareaRef.current?.focus();
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  if (!activeContact) return null;

  return (
    <div className="flex flex-1 flex-col overflow-hidden">
      {/* Header */}
      <div className="flex items-center justify-between border-b px-5 py-3">
        <div className="flex items-center gap-3">
          <div className="relative">
            <Avatar className="size-9">
              {activeContact.avatar ? (
                <AvatarImage
                  src={activeContact.avatar}
                  alt={activeContact.name}
                />
              ) : null}
              <AvatarFallback className="text-sm">
                {activeContact.name
                  .split(" ")
                  .map((n) => n[0])
                  .join("")
                  .slice(0, 2)}
              </AvatarFallback>
            </Avatar>
          </div>
          <div>
            <h2 className="text-sm font-semibold">{activeContact.name}</h2>
            <p className="text-muted-foreground text-xs">
              {activeContact.isGroup
                ? `${activeContact.members} members`
                : activeContact.status === "online"
                  ? "Active now"
                  : activeContact.status === "away"
                    ? "Away"
                    : "Offline"}
            </p>
          </div>
        </div>

        <div className="flex items-center gap-1">
          {!activeContact.isGroup && (
            <>
              <Button
                variant="ghost"
                size="icon"
                className="text-muted-foreground size-8"
              >
                <Phone className="size-4" />
              </Button>
              <Button
                variant="ghost"
                size="icon"
                className="text-muted-foreground size-8"
              >
                <Video className="size-4" />
              </Button>
            </>
          )}
          {activeContact.isGroup && (
            <Button
              variant="ghost"
              size="icon"
              className="text-muted-foreground size-8"
            >
              <Users className="size-4" />
            </Button>
          )}
          <Button
            variant="ghost"
            size="icon"
            className="text-muted-foreground size-8"
          >
            <MoreHorizontal className="size-4" />
          </Button>
          {isMobile && (
            <Button
              variant="ghost"
              size="icon"
              className="text-muted-foreground size-8"
              onClick={() => setMobileDrawerOpen(false)}
            >
              <ChevronDown className="size-4" />
            </Button>
          )}
        </div>
      </div>

      {/* Messages */}
      <div
        ref={messagesRef}
        className="flex-1 space-y-4 overflow-y-auto px-5 py-5"
      >
        {activeMessages.length === 0 && (
          <div className="flex h-full flex-col items-center justify-center gap-2">
            <div className="bg-muted flex size-12 items-center justify-center rounded-full">
              <Send className="text-muted-foreground size-5" />
            </div>
            <p className="text-muted-foreground text-sm">
              No messages yet. Say hello!
            </p>
          </div>
        )}
        {activeMessages.map((msg) => (
          <MessageBubble
            key={msg.id}
            message={msg}
            senderAvatarUrl={
              msg.sender === "other" && msg.senderName
                ? avatarByFirstName.get(msg.senderName)
                : undefined
            }
          />
        ))}
      </div>

      <div className="border-t px-4 py-3">
        <InputGroup className="bg-muted/50 h-auto min-h-0 rounded-xl py-2 pr-2 pl-2">
          <InputGroupTextarea
            ref={textareaRef}
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="Type a message..."
            rows={1}
            className="field-sizing-content max-h-32 min-h-9 py-1.5 pr-1 pl-1 text-sm leading-snug"
          />
          <InputGroupAddon
            align="inline-end"
            className="shrink-0 self-end py-0 pr-0 has-[>button]:mr-0">
            <InputGroupButton
              variant="primary"
              size="icon-sm"
              className="rounded-lg"
              onClick={handleSend}
              disabled={!input.trim()}
              aria-label="Send message"
            >
              <Send className="size-3.5" />
            </InputGroupButton>
          </InputGroupAddon>
        </InputGroup>
      </div>
    </div>
  );
}

"use client";

import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Button } from "@/components/ui/button";
