"use client";

import { useState } from "react";
import { cn } from "@/lib/utils";
import { Sidebar } from "@/components/app-pages/multi-step-form/components/sidebar";
import { StepRoleUseCase } from "@/components/app-pages/multi-step-form/components/step-role-use-case";
import { StepTemplate } from "@/components/app-pages/multi-step-form/components/step-template";
import { StepDataSource } from "@/components/app-pages/multi-step-form/components/step-data-source";
import { StepFirstFlow } from "@/components/app-pages/multi-step-form/components/step-first-flow";
import { StepInviteTeam } from "@/components/app-pages/multi-step-form/components/step-invite-team";

export interface OnboardingStep {
  id: string;
  title: string;
  completed: boolean;
  current: boolean;
  optional?: boolean;
}

const initialSteps: OnboardingStep[] = [
  { id: "role", title: "Role & Use Case", completed: false, current: true },
  {
    id: "template",
    title: "Choose a Template",
    completed: false,
    current: false,
  },
  {
    id: "data-source",
    title: "Data Source Setup",
    completed: false,
    current: false,
  },
  {
    id: "first-flow",
    title: "Build Your First Flow",
    completed: false,
    current: false,
    optional: true,
  },
  {
    id: "invite-team",
    title: "Invite Team",
    completed: false,
    current: false,
    optional: true,
  },
];

export default function Page() {
  const [currentStep, setCurrentStep] = useState(0);
  const [steps, setSteps] = useState<OnboardingStep[]>(initialSteps);

  const goToStep = (index: number) => {
    if (index < 0 || index >= steps.length) return;

    setSteps((prev) =>
      prev.map((step, i) => ({
        ...step,
        current: i === index,
        completed: i < index ? true : step.completed,
      })),
    );
    setCurrentStep(index);
  };

  const handleContinue = () => {
    goToStep(currentStep + 1);
  };

  const handleBack = () => {
    goToStep(currentStep - 1);
  };

  const stepComponents = [
    <StepRoleUseCase key="role" onContinue={handleContinue} />,
    <StepTemplate
      key="template"
      onContinue={handleContinue}
      onBack={handleBack}
    />,
    <StepDataSource
      key="data-source"
      onContinue={handleContinue}
      onBack={handleBack}
    />,
    <StepFirstFlow
      key="first-flow"
      onContinue={handleContinue}
      onBack={handleBack}
    />,
    <StepInviteTeam key="invite-team" onBack={handleBack} />,
  ];

  return (
    <div className="flex min-h-screen flex-col lg:flex-row">
      <Sidebar steps={steps} currentStep={currentStep} onStepClick={goToStep} />

      <main className="flex-1 overflow-y-auto pb-20 lg:pb-0">
        {stepComponents[currentStep]}
      </main>

      <div className="bg-background fixed right-0 bottom-0 left-0 border-t p-4 lg:hidden">
        <div className="flex items-center justify-center gap-2">
          {steps.map((step) => (
            <div
              key={step.id}
              className={cn(
                "h-2 w-2 rounded-full transition-colors",
                step.completed
                  ? "bg-primary"
                  : step.current
                    ? "bg-primary"
                    : "bg-muted-foreground/30",
              )}
            />
          ))}
        </div>
        <p className="text-muted-foreground mt-2 text-center text-sm">
          Step {currentStep + 1} of {steps.length}
        </p>
      </div>
    </div>
  );
}

import { cn } from "@/lib/utils";
import { CheckIcon, BoxIcon } from "lucide-react";
import type { OnboardingStep } from "../page";

interface SidebarProps {
  steps: OnboardingStep[];
  currentStep: number;
  onStepClick: (index: number) => void;
}

export const Sidebar = ({ steps, currentStep, onStepClick }: SidebarProps) => {
  return (
    <div className="hidden w-80 flex-col bg-gradient-to-b from-black to-indigo-700 p-6 text-white lg:flex">
      <div className="mb-12 flex items-center gap-3 pt-4">
        <BoxIcon className="size-6" />
      </div>

      <div className="flex-1 space-y-1">
        {steps.map((step, index) => (
          <button
            key={step.id}
            onClick={() => {
              if (step.completed || index <= currentStep) onStepClick(index);
            }}
            className={cn(
              "flex w-full items-center gap-4 rounded-lg p-3 text-left transition-all duration-200",
              step.current && "bg-white/10",
              (step.completed || index <= currentStep) && "cursor-pointer",
            )}
          >
            <div
              className={cn(
                "flex size-6 shrink-0 items-center justify-center rounded-full border-2 transition-colors",
                step.completed
                  ? "border-green-400 bg-green-400"
                  : step.current
                    ? "border-white bg-transparent"
                    : "border-white/30",
              )}
            >
              {step.completed ? (
                <CheckIcon className="text-gray-800 size-3.5" />
              ) : step.current ? (
