              </span>
              {step.optional && (
                <span className="text-white/50 block text-xs">Optional</span>
              )}
            </div>
          </button>
        ))}
      </div>

      <div className="text-white/60 mt-auto flex justify-between pt-8 text-sm">
        <span>Terms of Service</span>
        <span>Help Center</span>
