type TodoStore = {
    sections: Section[];
    viewMode: "kanban" | "list";
    setSections: (sections: Section[]) => void;
    setViewMode: (mode: "kanban" | "list") => void;
    addTodo: (sectionId: string, text: string, priority: Priority) => void;
    deleteTodo: (todoId: string) => void;
    toggleTodo: (todoId: string) => void;
    updateTodoPriority: (todoId: string, priority: Priority) => void;
};

export const useTodoStore = create<TodoStore>()(
    persist(
        (set) => ({
            sections: INITIAL_SECTIONS,
            viewMode: "list",

            setSections: (sections) => set({ sections }),
            setViewMode: (viewMode) => set({ viewMode }),

            addTodo: (sectionId, text, priority) =>
                set((state) => ({
                    sections: state.sections.map((s) =>
                        s.id === sectionId
                            ? {
                                ...s,
                                todos: [
                                    ...s.todos,
                                    {
                                        id: crypto.randomUUID(),
                                        text,
                                        completed: false,
                                        priority,
                                        createdAt: new Date().toISOString()
                                    }
                                ]
                            }
                            : s
                    )
                })),

            deleteTodo: (todoId) =>
                set((state) => ({
                    sections: state.sections.map((s) => ({
                        ...s,
                        todos: s.todos.filter((t) => t.id !== todoId)
                    }))
                })),

            toggleTodo: (todoId) =>
                set((state) => ({
                    sections: state.sections.map((s) => ({
                        ...s,
                        todos: s.todos.map((t) =>
                            t.id === todoId ? { ...t, completed: !t.completed } : t
                        )
                    }))
                })),

            updateTodoPriority: (todoId, priority) =>
                set((state) => ({
                    sections: state.sections.map((s) => ({
                        ...s,
                        todos: s.todos.map((t) => (t.id === todoId ? { ...t, priority } : t))
                    }))
                }))
        }),
        { name: "todo-app-storage" }
    )
);

export type Priority = "high" | "medium" | "low";

export interface Todo {
    id: string;
    text: string;
    completed: boolean;
    priority: Priority;
    createdAt: string;
}

export interface Section {
    id: string;
    title: string;
    color: "violet" | "amber" | "emerald";
    todos: Todo[];
}

"use client";

import { useState } from "react";
import {
  DndContext,
  DragOverlay,
  closestCorners,
  PointerSensor,
  useSensor,
  useSensors,
  type DragStartEvent,
  type DragOverEvent,
  type DragEndEvent,
} from "@dnd-kit/core";
import { arrayMove } from "@dnd-kit/sortable";
import { restrictToWindowEdges } from "@dnd-kit/modifiers";
import { CheckSquare2, LayoutGrid, List } from "lucide-react";
import { Toggle } from "@/components/ui/toggle";
import { useTodoStore } from "../store";
import { TodoColumn } from "@/components/app-pages/todo-list-app-page/components/todo-column";
import { TodoListView } from "@/components/app-pages/todo-list-app-page/components/todo-list-view";
import { TodoCardContent } from "@/components/app-pages/todo-list-app-page/components/todo-card";
import { TodoRowContent } from "@/components/app-pages/todo-list-app-page/components/todo-row";
import { Section, Todo } from "../types";

export function TodoApp() {
  const { sections, setSections, viewMode, setViewMode } = useTodoStore();
  const [activeId, setActiveId] = useState<string | null>(null);

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 8 } }),
  );

  const getContainerIdOf = (id: string): string | null => {
    if (sections.some((s) => s.id === id)) return id;
    return (
      sections.find((s) => s.todos.some((t: Todo) => t.id === id))?.id ?? null
    );
  };

  const getActiveTodo = (): Todo | null => {
    if (!activeId) return null;
    for (const section of sections) {
      const todo = section.todos.find((t: Todo) => t.id === activeId);
      if (todo) return todo;
    }
    return null;
  };

  const handleDragStart = ({ active }: DragStartEvent) => {
    setActiveId(String(active.id));
  };

  const handleDragOver = ({ active, over }: DragOverEvent) => {
    if (!over) return;
    const activeId = String(active.id);
    const overId = String(over.id);

    const activeContainerId = getContainerIdOf(activeId);
    const overContainerId = getContainerIdOf(overId);

    if (!activeContainerId || !overContainerId) return;
    if (activeContainerId === overContainerId) return;

    setSections(
      sections.map((s: Section) => {
        if (s.id === activeContainerId) {
          return {
            ...s,
            todos: s.todos.filter((t: Todo) => t.id !== activeId),
          };
        }
        if (s.id === overContainerId) {
          const todo = sections
            .find((sec) => sec.id === activeContainerId)!
            .todos.find((t: Todo) => t.id === activeId)!;

          const overTodoIdx = s.todos.findIndex((t: Todo) => t.id === overId);
          const newTodos = [...s.todos];

          if (overTodoIdx >= 0) {
            newTodos.splice(overTodoIdx, 0, todo);
          } else {
            newTodos.push(todo);
          }

          return { ...s, todos: newTodos };
        }
        return s;
      }),
    );
  };

  const handleDragEnd = ({ active, over }: DragEndEvent) => {
    setActiveId(null);
    if (!over) return;

    const activeId = String(active.id);
    const overId = String(over.id);

    if (activeId === overId) return;

    const activeContainerId = getContainerIdOf(activeId);
    const overContainerId = getContainerIdOf(overId);

    if (!activeContainerId || !overContainerId) return;
    if (activeContainerId !== overContainerId) return;

    const section = sections.find((s) => s.id === activeContainerId)!;
    const fromIdx = section.todos.findIndex((t: Todo) => t.id === activeId);
    const toIdx = section.todos.findIndex((t: Todo) => t.id === overId);

    if (fromIdx !== -1 && toIdx !== -1 && fromIdx !== toIdx) {
      setSections(
        sections.map((s: Section) =>
          s.id === activeContainerId
            ? { ...s, todos: arrayMove(s.todos, fromIdx, toIdx) }
            : s,
        ),
      );
    }
  };

  const totalTasks = sections.reduce(
    (sum, s: Section) => sum + s.todos.length,
    0,
  );
  const doneTasks = sections.reduce(
    (sum, s: Section) => sum + s.todos.filter((t: Todo) => t.completed).length,
    0,
  );
  const activeTodo = getActiveTodo();

  return (
    <div className="bg-background flex h-screen flex-col overflow-hidden">
      {/* Header */}
      <header className="shrink-0 border-b px-5 py-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-primary/10 flex size-8 items-center justify-center rounded-lg">
              <CheckSquare2 className="text-primary size-4" />
            </div>
            <div>
              <h1 className="text-sm font-semibold leading-tight">My Tasks</h1>
              <p className="text-muted-foreground text-xs">
                {doneTasks} of {totalTasks} completed
              </p>
            </div>
          </div>

          <div className="flex items-center gap-3">
            <div className="hidden items-center gap-2 sm:flex">
              <div className="h-1.5 w-32 overflow-hidden rounded-full bg-muted">
                <div
                  className="bg-primary h-full rounded-full transition-all"
                  style={{
                    width:
                      totalTasks > 0
                        ? `${Math.round((doneTasks / totalTasks) * 100)}%`
                        : "0%",
                  }}
                />
              </div>
              <span className="text-muted-foreground w-8 text-right text-xs tabular-nums">
                {totalTasks > 0
                  ? Math.round((doneTasks / totalTasks) * 100)
                  : 0}
                %
              </span>
            </div>

            <div className="flex rounded-lg border p-0.5">
              <Toggle
                pressed={viewMode === "kanban"}
                onPressedChange={() => setViewMode("kanban")}
                size="sm"
                className="data-[state=on]:bg-muted size-7 rounded-md"
              >
                <LayoutGrid className="size-3.5" />
              </Toggle>
              <Toggle
                pressed={viewMode === "list"}
                onPressedChange={() => setViewMode("list")}
                size="sm"
                className="data-[state=on]:bg-muted size-7 rounded-md"
              >
                <List className="size-3.5" />
              </Toggle>
            </div>
          </div>
        </div>
      </header>

      {/* Board */}
      <div className="flex-1 overflow-auto p-4 lg:p-5">
        <DndContext
          sensors={sensors}
          collisionDetection={closestCorners}
          modifiers={[restrictToWindowEdges]}
          onDragStart={handleDragStart}
          onDragOver={handleDragOver}
          onDragEnd={handleDragEnd}
        >
          {viewMode === "kanban" ? (
            <div className="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-3">
              {sections.map((section: Section) => (
                <TodoColumn key={section.id} section={section} />
              ))}
            </div>
          ) : (
            <TodoListView />
          )}

          <DragOverlay>
            {activeTodo ? (
              viewMode === "list" ? (
                <TodoRowContent todo={activeTodo} overlay />
              ) : (
                <TodoCardContent todo={activeTodo} overlay />
              )
            ) : null}
          </DragOverlay>
        </DndContext>
      </div>
    </div>
  );
}

