      style={style}
      className={cn(isDragging && "opacity-0")}
    >
      <div
        ref={setActivatorNodeRef}
        {...attributes}
        {...listeners}
        className="cursor-grab active:cursor-grabbing"
      >
        <TodoRowContent todo={todo} />
      </div>
    </div>
  );
}
